import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Capability Discipline at the Language Level","description":"","frontmatter":{"title":"Capability Discipline at the Language Level","type":"adr","date":"2026-08-30T00:00:00.000Z","status":"proposed","status_note":"Accepted — capabilities are declared statically and enforced at the eval boundary."},"headers":[],"relativePath":"handl/project/adrs/0046-capability-discipline-at-the-language-level.md","filePath":"vendored/handl/project/adrs/0046-capability-discipline-at-the-language-level.md"}`),a={name:`handl/project/adrs/0046-capability-discipline-at-the-language-level.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0046-capability-discipline-at-the-language-level" tabindex="-1">ADR-0046: Capability Discipline at the Language Level <a class="header-anchor" href="#adr-0046-capability-discipline-at-the-language-level" aria-label="Permalink to “ADR-0046: Capability Discipline at the Language Level”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong><code>CapabilitySet</code> summarizes a <code>Language</code> statically</strong> — host function names, whether it has <code>vau</code>, and whether it can <code>eval</code> or <code>compile</code>.</li><li><strong>It is computed by scanning eval schemes</strong>: <code>Foreign</code> adds a name, <code>Vau</code> implies eval, and <code>eval</code>/<code>run</code>/<code>compile</code> names set the corresponding flags.</li><li><strong><code>CapabilityPolicy</code> declares what a context allows</strong> — host fns, <code>vau</code>, <code>eval</code>, <code>compile</code>.</li><li><strong>A static check at the <code>eval</code>/<code>run</code>/<code>compile</code> boundary</strong> denies before dispatch; it reads <code>Language</code> data, not the running program.</li><li><strong><code>LanguageRegistry</code> carries policies</strong>, attached at registration time by the host that builds it.</li><li><strong>Sub-runtimes inherit a narrowed policy</strong> — a sandboxed language cannot escalate by evaluating a more privileged one.</li><li><strong><code>capabilities(handle)</code> is a read-only host function</strong> for handl programs, and <code>CapabilityDenied</code> surfaces a denial to the program.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Capabilities were enforced only at runtime, so a language could smuggle in <code>vau</code>/<code>eval</code>/<code>compile</code> or an unlisted host function and no one could inspect the requirement. A static set plus a policy check at the boundary makes the sandbox reviewable before execution.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Runtime instrumentation</strong> — the check is static and once per boundary.</li><li><strong>Per-call policy changes</strong> — policies attach at registration.</li><li><strong>Capability escalation via sub-runtimes</strong> — inherited policies are narrowed.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Sandboxing is inspectable and cheap; capability changes are data changes.</li><li>A host must declare a policy per registered language.</li><li><code>capabilities()</code> lets handl programs reject unsafe languages.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>crates/handl-language/</code> — <code>CapabilitySet</code>, <code>CapabilityPolicy</code>.</li><li><code>handl-runtime/</code> — registry and boundary check.</li><li><code>capabilities(handle)</code> host function; denial tests.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+Struct shapes, computation rules, boundary check and inheritance: +<a href="./../design/0046-capability-discipline-at-the-language-level.html"><code>design/0046-capability-discipline-at-the-language-level.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};